package org.sleepwell.app;
import android.app.*;import android.content.*;import android.graphics.Rect;import android.os.*;import android.view.*;import android.view.inspector.WindowInspector;import android.widget.*;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.UiDevice;import org.junit.Test;import java.io.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import static org.junit.Assert.*;
/** Actual native review/cancel/recreate/handoff, fake calendar launcher and private SQLite only. */
public final class CalendarEventExportFlowTest {
    final Instrumentation i=InstrumentationRegistry.getInstrumentation();final Context c=i.getTargetContext();final UiDevice device=UiDevice.getInstance(i);CalendarEventExportActivity activity;final List<Activity> owned=new CopyOnWriteArrayList<>();final List<Intent> handedOff=new CopyOnWriteArrayList<>();volatile boolean fail;
    void await(java.util.function.BooleanSupplier condition)throws Exception{long end=SystemClock.elapsedRealtime()+8000;while(!condition.getAsBoolean()&&SystemClock.elapsedRealtime()<end)Thread.sleep(20);assertTrue("Calendar review state",condition.getAsBoolean());}
    View find(View root,String label){if(root==null)return null;if(label.contentEquals(root.getContentDescription()==null?"":root.getContentDescription())||root instanceof TextView&&label.contentEquals(((TextView)root).getText()))return root;if(root instanceof ViewGroup group)for(int n=0;n<group.getChildCount();n++){View found=find(group.getChildAt(n),label);if(found!=null)return found;}return null;}
    View focused(){for(View root:WindowInspector.getGlobalWindowViews())if(root.hasWindowFocus()&&root.isAttachedToWindow()&&root.getContext().getPackageName().equals(c.getPackageName()))return root;return null;}
    boolean shown(String label){boolean[] yes={false};i.runOnMainSync(()->yes[0]=activity!=null&&!activity.isDestroyed()&&focused()==activity.getWindow().getDecorView()&&find(focused(),label)!=null);return yes[0];}
    void click(String label)throws Exception{await(()->shown(label));Rect[] bounds={null};View owner=activity.getWindow().getDecorView();await(()->{boolean[] yes={false};i.runOnMainSync(()->{View target=find(owner,label);while(!target.isClickable()&&target.getParent() instanceof View)target=(View)target.getParent();target.requestRectangleOnScreen(new Rect(0,0,target.getWidth(),target.getHeight()),true);Rect visible=new Rect();yes[0]=target.isEnabled()&&target.isClickable()&&target.getGlobalVisibleRect(visible)&&visible.width()==target.getWidth()&&visible.height()==target.getHeight();});return yes[0];});frame(owner);i.runOnMainSync(()->{assertSame(owner,focused());View target=find(owner,label);while(!target.isClickable()&&target.getParent() instanceof View)target=(View)target.getParent();assertTrue(target.getHeight()>=Design.dp(c,48));int[] position=new int[2];target.getLocationOnScreen(position);bounds[0]=new Rect(position[0],position[1],position[0]+target.getWidth(),position[1]+target.getHeight());});assertTrue(device.click(bounds[0].centerX(),bounds[0].centerY()));}
    void frame(View owner)throws Exception{CountDownLatch commit=new CountDownLatch(1);i.runOnMainSync(()->{assertSame(owner,focused());owner.getViewTreeObserver().registerFrameCommitCallback(commit::countDown);owner.invalidate();});assertTrue(commit.await(5,TimeUnit.SECONDS));}
    void capture(String name)throws Exception{await(()->shown("Open calendar"));frame(activity.getWindow().getDecorView());File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(device.takeScreenshot(new File(folder,"calendar-event-"+name+".png")));}
    void launch(long id)throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(CalendarEventExportActivity.class.getName(),null,false);try{c.startActivity(new Intent(c,CalendarEventExportActivity.class).putExtra("record",id).putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));activity=(CalendarEventExportActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}await(()->shown("Open calendar"));}
    @Test public void reviewNoteChoiceRecreationMissingCalendarAndRetryDoNotModifySavedNight()throws Exception{
        assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",device.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(AlarmService.active);assertFalse(TrackingService.running);String database="calendar-event-flow-"+UUID.randomUUID()+".db";Records.Factory prior=Records.factory;CalendarEventExport.Port originalPort=CalendarEventExport.port;Map<String,?> prefs=new HashMap<>(Prefs.of(c).getAll());Application app=(Application)c.getApplicationContext();Application.ActivityLifecycleCallbacks observer=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle state){owned.add(a);assertTrue("Only calendar review",a instanceof CalendarEventExportActivity);}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle state){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(observer);
        try(Store store=new Store(c,database)){Records.factory=ctx->new Store(ctx,database);CalendarEventExport.port=(owner,intent)->{if(fail)throw new ActivityNotFoundException();handedOff.add(new Intent(intent));};long end=System.currentTimeMillis()-86400000;RecordDraft draft=new RecordDraft(end-28800000,end);draft.note="Private calendar note";long id=Records.create(store,draft,ZoneId.of("UTC"),System.currentTimeMillis());String before=BackupFingerprint.read(store);launch(id);assertTrue(handedOff.isEmpty());capture("default");click("Include my note");await(()->shown(draft.note));CalendarEventExportActivity previous=activity;Instrumentation.ActivityMonitor monitor=i.addMonitor(CalendarEventExportActivity.class.getName(),null,false);try{i.runOnMainSync(previous::recreate);activity=(CalendarEventExportActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}await(()->shown(draft.note));capture("recreated");assertTrue(handedOff.isEmpty());fail=true;click("Open calendar");await(()->shown("No compatible calendar app was found."));capture("unavailable");assertTrue(handedOff.isEmpty());fail=false;click("Open calendar");await(()->handedOff.size()==1);await(()->shown("Calendar draft opened. Saving is handled by your calendar app."));assertTrue(handedOff.get(0).getStringExtra(android.provider.CalendarContract.Events.DESCRIPTION).contains(draft.note));capture("opened");assertEquals(before,BackupFingerprint.read(store));assertEquals(prefs,Prefs.of(c).getAll());}
        catch(Exception|AssertionError failed){try{File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());device.takeScreenshot(new File(folder,"calendar-event-failure.png"));device.dumpWindowHierarchy(new File(folder,"calendar-event-failure.xml"));}catch(Exception diagnostic){failed.addSuppressed(diagnostic);}throw failed;}
        finally{try{i.runOnMainSync(()->{for(Activity a:owned)if(!a.isDestroyed())a.finish();});await(()->owned.stream().allMatch(Activity::isDestroyed));for(Activity a:owned)assertTrue(((CalendarEventExportActivity)a).awaitReaders(8000));}finally{app.unregisterActivityLifecycleCallbacks(observer);Records.factory=prior;CalendarEventExport.port=originalPort;assertTrue(c.deleteDatabase(database));assertEquals(prefs,Prefs.of(c).getAll());assertFalse(AlarmService.active);assertFalse(TrackingService.running);}}
    }
}
